Result<Ref<IteratorBase>> Connection::read_impl(
    const dynamic::SelectFrom& _query) {
  const auto sql = postgres::to_sql_impl(_query);
  try {
    return Ref<IteratorBase>(Ref<Iterator>::make(sql, conn_));
  } catch (std::exception& e) {
    return error(e.what());
  }
}

