    using Type = std::remove_cvref_t<decltype(_c)>;
    if constexpr (std::is_same_v<Type, dynamic::Column>) {
      if (_c.alias) {
        return *_c.alias + "." + wrap_in_quotes(_c.name);
      } else {
        return wrap_in_quotes(_c.name);
      }
    } else {
      return _c.val.visit(handle_value);
    }
  });
}

